81: int ProcessHandleImpl::wait(int options) const
82: {
83: 	if (_hasStatus.load()) return _pid;
84: 	int status;
85: 	int rc;
86: 	do
87: 	{
88: 		rc = ::waitpid(_pid, &status, options);
89: 	}
90: 	while (rc < 0 && errno == EINTR);
91: 	if (rc == _pid)
92: 	{
93: 		_status.store(status);
94: 		_hasStatus.store(true);
95: 		// N.B. _hasStatus must be stored before _event.set()
96: 		// because the ECHILD/WNOHANG path checks tryWait(0) && _hasStatus
97: 		_event.set();
98: 	}
99: 	else if (rc < 0 && errno == ECHILD)
100: 	{
101: 		// Another thread reaped the process; synchronize with its status update.
102: 		// Preserve the requested wait semantics:
103: 		//  - blocking waits block until the status has been published
104: 		//  - WNOHANG waits remain non-blocking
105: 		if (options & WNOHANG)
106: 		{
107: 			if (_event.tryWait(0) && _hasStatus.load())
108: 				rc = _pid;
109: 			else
110: 				rc = 0;
111: 		}
112: 		else
113: 		{
114: 			_event.wait();
115: 			if (_hasStatus.load())
116: 				rc = _pid;
117: 			else
118: 				throw SystemException("Lost process status (internal error)", NumberFormatter::format(_pid));
119: 		}
120: 	}
121: 
122: 	return rc;
123: }
